class SessionConfigOptionSelect(SessionConfigSelect):
    id: str
    '\n    Unique identifier for the configuration option.\n    '
    name: str
    '\n    Human-readable label for the option.\n    '
    description: Optional[str] = None
    '\n    Optional description for the Client to display to the user.\n    '
    category: Optional[Union[Literal['mode'], Literal['model'], Literal['model_config'], Literal['thought_level'], Dict[str, Any]]] = None
    '\n    Optional semantic category for this option (UX only).\n    '
    field_meta: Annotated[Optional[Dict[str, Any]], Field(alias='_meta')] = None
    '\n    The _meta property is reserved by ACP to allow clients and agents to attach additional\n    metadata to their interactions. Implementations MUST NOT make assumptions about values at\n    these keys.\n\n    See protocol docs: [Extensibility](https://agentclientprotocol.com/protocol/extensibility)\n    '
    type: Literal['select']

    @field_validator('category', 'description', mode='wrap')
    @classmethod
    def _salvage_on_error_0(cls, value: Any, handler: Any) -> Any:
        return salvage_on_error(value, handler, lambda: None)

@param_model(NewSessionRequest)
async def new_session(self, cwd: str, additional_directories: list[str] | None=None, mcp_servers: list[HttpMcpServer | SseMcpServer | AcpMcpServer | McpServerStdio] | None=None, **kwargs: Any) -> NewSessionResponse:
    resolved_mcp_servers = mcp_servers or []
    return await request_model(self._conn, AGENT_METHODS['session_new'], NewSessionRequest(cwd=cwd, additional_directories=additional_directories, mcp_servers=resolved_mcp_servers, field_meta=kwargs or None), NewSessionResponse)

@param_model(LoadSessionRequest)
async def load_session(self, cwd: str, session_id: str, mcp_servers: list[HttpMcpServer | SseMcpServer | AcpMcpServer | McpServerStdio] | None=None, additional_directories: list[str] | None=None, **kwargs: Any) -> LoadSessionResponse:
    resolved_mcp_servers = mcp_servers or []
    return await request_model_from_dict(self._conn, AGENT_METHODS['session_load'], LoadSessionRequest(cwd=cwd, additional_directories=additional_directories, mcp_servers=resolved_mcp_servers, session_id=session_id, field_meta=kwargs or None), LoadSessionResponse)

@param_model(SetSessionModeRequest)
async def set_session_mode(self, session_id: str, mode_id: str, **kwargs: Any) -> SetSessionModeResponse:
    return await request_model_from_dict(self._conn, AGENT_METHODS['session_set_mode'], SetSessionModeRequest(mode_id=mode_id, session_id=session_id, field_meta=kwargs or None), SetSessionModeResponse)

@param_model(PromptRequest)
async def prompt(self, session_id: str, prompt: list[TextContentBlock | ImageContentBlock | AudioContentBlock | ResourceContentBlock | EmbeddedResourceContentBlock], **kwargs: Any) -> PromptResponse:
    try:
        response = await request_model(self._conn, AGENT_METHODS['session_prompt'], PromptRequest(prompt=prompt, session_id=session_id, field_meta=kwargs or None), PromptResponse)
    except Exception:
        await self._session_updates.wait(session_id)
        raise
    await self._session_updates.wait(session_id)
    return response
